begin;
create extension if not exists pgcrypto;
create table if not exists public.angelcare_marketplace_catalog_items(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('CAT-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),item_key text unique not null,slug text unique not null,kind text not null check(kind in('service','product','training','audit','saas_module','kit')),name_fr text not null,short_description_fr text,description_fr text,source_locale text not null default 'fr' check(source_locale='fr'),status text not null default 'draft' check(status in('draft','review','approved','published','paused','archived')),territory_id uuid,currency_label text not null default 'Dh',price_mode text not null default 'quote_only' check(price_mode in('fixed','starting_from','quote_only','subscription')),price_amount numeric(14,2),featured boolean not null default false,availability_status text not null default 'configuration_required' check(availability_status in('available','unavailable','configuration_required','out_of_stock','territory_restricted')),owner_id uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_catalog_variants(id uuid primary key default gen_random_uuid(),catalog_item_id uuid not null references public.angelcare_marketplace_catalog_items(id) on delete cascade,variant_key text not null,name_fr text not null,configuration jsonb not null default '{}',price_delta numeric(14,2),status text not null default 'active' check(status in('active','paused','archived')),sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(catalog_item_id,variant_key));
create table if not exists public.angelcare_marketplace_catalog_availability(id uuid primary key default gen_random_uuid(),catalog_item_id uuid not null references public.angelcare_marketplace_catalog_items(id) on delete cascade,territory_id uuid,city_zone_id uuid,audience text not null default 'all',available boolean not null default false,capacity_limit int,starts_at timestamptz,ends_at timestamptz,reason text,updated_by uuid,updated_at timestamptz not null default now(),unique(catalog_item_id,territory_id,city_zone_id,audience));
create table if not exists public.angelcare_marketplace_suppliers(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('SUP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),supplier_code text unique not null,legal_name text not null,display_name text not null,status text not null default 'prospect' check(status in('prospect','qualification','approved','active','suspended','archived')),territory_id uuid,quality_status text not null default 'unreviewed' check(quality_status in('unreviewed','pending','approved','conditional','rejected','expired')),primary_contact jsonb not null default '{}',payment_terms text,owner_id uuid,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_supplier_offers(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.angelcare_marketplace_suppliers(id) on delete cascade,catalog_item_id uuid not null references public.angelcare_marketplace_catalog_items(id) on delete cascade,supplier_sku text,unit_cost numeric(14,2),currency_label text not null default 'Dh',minimum_order numeric(14,2),lead_time_days int,status text not null default 'draft' check(status in('draft','review','approved','active','suspended','archived')),quality_evidence jsonb not null default '[]',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(supplier_id,catalog_item_id,supplier_sku));
create table if not exists public.angelcare_marketplace_quote_baskets(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('BASK-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),basket_status text not null default 'draft' check(basket_status in('draft','submitted','qualified','converted','expired','cancelled')),currency_label text not null default 'Dh',territory_id uuid,family_account_id uuid,tenant_id uuid,contact_email text,contact_phone text,subtotal numeric(14,2) not null default 0,discount_total numeric(14,2) not null default 0,tax_total numeric(14,2) not null default 0,grand_total numeric(14,2) not null default 0,expires_at timestamptz,created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_quote_basket_items(id uuid primary key default gen_random_uuid(),basket_id uuid not null references public.angelcare_marketplace_quote_baskets(id) on delete cascade,catalog_item_id uuid not null references public.angelcare_marketplace_catalog_items(id),catalog_variant_id uuid references public.angelcare_marketplace_catalog_variants(id),quantity numeric(12,2) not null default 1,unit_price numeric(14,2),line_total numeric(14,2),configuration jsonb not null default '{}',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_commission_rules(id uuid primary key default gen_random_uuid(),rule_key text unique not null,name_fr text not null,scope_type text not null check(scope_type in('global','territory','catalog_item','supplier','partner')),scope_id uuid,commission_type text not null check(commission_type in('percentage','fixed','tiered')),commission_value numeric(14,4),tiers jsonb not null default '[]',status text not null default 'draft' check(status in('draft','review','approved','active','paused','archived')),starts_at timestamptz,ends_at timestamptz,owner_id uuid,approved_by uuid,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_catalog_events(id uuid primary key default gen_random_uuid(),catalog_item_id uuid references public.angelcare_marketplace_catalog_items(id) on delete cascade,event_type text not null,payload jsonb not null default '{}',actor_id uuid,created_at timestamptz not null default now());
create index if not exists angelcare_catalog_items_public_idx on public.angelcare_marketplace_catalog_items(status,availability_status,kind,featured desc);
create index if not exists angelcare_quote_baskets_status_idx on public.angelcare_marketplace_quote_baskets(basket_status,updated_at desc);
insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values
('marketplace.catalog.view','Voir le catalogue','Marketplace Commerce',false),('marketplace.catalog.manage','Gérer le catalogue','Marketplace Commerce',true),('marketplace.catalog.review','Réviser le catalogue','Marketplace Commerce',true),('marketplace.catalog.publish','Publier le catalogue','Marketplace Commerce',true),('marketplace.catalog.availability.manage','Gérer la disponibilité','Marketplace Commerce',true),('marketplace.catalog.suppliers.view','Voir les fournisseurs','Marketplace Commerce',false),('marketplace.catalog.suppliers.manage','Gérer les fournisseurs','Marketplace Commerce',true),('marketplace.catalog.commissions.view','Voir les commissions','Marketplace Commerce',false),('marketplace.catalog.commissions.manage','Gérer les commissions','Marketplace Commerce',true),('marketplace.quote_basket.create','Créer un panier de devis','Marketplace Commerce',true),('marketplace.quote_basket.view','Voir les paniers de devis','Marketplace Commerce',false),('marketplace.quote_basket.manage','Gérer les paniers de devis','Marketplace Commerce',true),('marketplace.catalog.export','Exporter le catalogue','Marketplace Commerce',true)
on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and (p.permission_key like 'marketplace.catalog.%' or p.permission_key like 'marketplace.quote_basket.%') on conflict do nothing;
update public.angelcare_marketplace_modules set status='enabled',enabled=true,health_status='healthy',route_prefix='/angelcare-marketplace/admin/marketplace',required_permissions=array['marketplace.catalog.view']::text[],version=version+1,updated_at=now() where module_key='marketplace.core' or introduced_by_mega_zip=9;
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.core.enabled','Marketplace Core','Catalogue unifié, disponibilité, fournisseurs, paniers et commissions.',true,'active','Ultra Delivery 2/5') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
alter table public.angelcare_marketplace_catalog_items enable row level security;alter table public.angelcare_marketplace_catalog_variants enable row level security;alter table public.angelcare_marketplace_catalog_availability enable row level security;alter table public.angelcare_marketplace_suppliers enable row level security;alter table public.angelcare_marketplace_supplier_offers enable row level security;alter table public.angelcare_marketplace_quote_baskets enable row level security;alter table public.angelcare_marketplace_quote_basket_items enable row level security;alter table public.angelcare_marketplace_commission_rules enable row level security;alter table public.angelcare_marketplace_catalog_events enable row level security;
revoke all on table public.angelcare_marketplace_catalog_items,public.angelcare_marketplace_catalog_variants,public.angelcare_marketplace_catalog_availability,public.angelcare_marketplace_suppliers,public.angelcare_marketplace_supplier_offers,public.angelcare_marketplace_quote_baskets,public.angelcare_marketplace_quote_basket_items,public.angelcare_marketplace_commission_rules,public.angelcare_marketplace_catalog_events from anon,authenticated;
grant all on table public.angelcare_marketplace_catalog_items,public.angelcare_marketplace_catalog_variants,public.angelcare_marketplace_catalog_availability,public.angelcare_marketplace_suppliers,public.angelcare_marketplace_supplier_offers,public.angelcare_marketplace_quote_baskets,public.angelcare_marketplace_quote_basket_items,public.angelcare_marketplace_commission_rules,public.angelcare_marketplace_catalog_events to service_role;
commit;
